-- Venue Live Guest "Wedding Gothic". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara gothic), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'gothic', 'Wedding Gothic (dark romance)', 'gothic', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 138, 'center 38%',
  $t${"name":"Gothic","orn":"diamond","ui":{"ivory":"#F6EEE8","white":"#FFFFFF","soft":"#E8D3D0","soft2":"#B8838B","accent":"#7A1226","deep":"#2B0E16","ink":"#2A1218","mute":"#85626A","line":"#E3CFC9","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F5EAE2","ink":"#2A1218","accent":"#7A1226","gold":"#C9A24A","leaf":"#E8D3D0","hbg":"rgba(246,238,232,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(43,14,22,.9)","acc":"#F2C86B","on":"#2A1218"},"scr":{"wine":"#2B0E16","veil":"246,238,232"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'gothic');
